      {
        product: { id: "x", name: "Widget", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.name).toBe("Widget");
    expect(result[0].product.weightGrams).toBe(500);
    expect(result[0].product.currency).toBe("EUR");
    expect(result[0].product.unitPriceCents).toBe(200);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };

    await expect(
      refreshPrices([makeLine("a", 100, 1)], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };

    await expect(
      refreshPrices([makeLine("a", 100, 1)], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };

    await expect(
      refreshPrices([makeLine("a", 100, 1)], fetcher),
    ).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty input", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

function makeProduct(id: string, priceCents: number, weightGrams?: number): Product {
  return { id, name: `Product ${id}`, unitPriceCents: priceCents, weightGrams };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding same product twice", () => {
      const cart = new Cart();
      const p = makeProduct("a", 100);
      cart.add(p, 2);
      cart.add(p, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 0)).toThrow(RangeError);
      expect(() => cart.add(makeProduct("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 5)).toThrow(
        "Product x is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2);
      cart.add(makeProduct("b", 200), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate internal state", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2);
      const snap = cart.snapshot();
      snap[0].quantity = 999;
      snap[0].product.unitPriceCents = 0;
      // internal state unchanged
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(200);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2); // 200
      cart.add(makeProduct("b", 300), 3); // 900
      expect(cart.totals().subtotalCents).toBe(1100);
    });

    it("returns all-zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("applies discount from injected policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1000);
      expect(t.discountCents).toBe(200);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount exceeds subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 500), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(500); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 500), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(makeProduct("a", 1000), 1);
      const t = cart.totals();
      // Tax called with discounted subtotal = 1000 - 200 = 800
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(t.taxCents).toBe(80);
    });

    it("computes shipping against discounted subtotal and lines", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(makeProduct("a", 500), 1);
      const t = cart.totals();
      // Shipping called with discounted subtotal = 500 - 100 = 400
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        400,
      );
      expect(t.shippingCents).toBe(599);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(makeProduct("a", 1000), 1);
      const t = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
      expect(t.totalCents).toBe(900 + 72 + 500);
    });

    it("uses default config when none provided", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      const t = cart.totals();
      // NoDiscount, NoTax, FreeShipping
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for simple checkout", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(200),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0].product.unitPriceCents).toBe(200);
      expect(result.totals.subtotalCents).toBe(400); // 200 * 2
    });

    it("checks inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(200);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item not available", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );

      try {
        await cart.checkout({ inventoryChecker });
      } catch (err) {
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available=true but quantity insufficient)", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("uses asyncTaxProvider when supplied", async () => {
