toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

function makeLine(
  id: string,
  quantity: number,
  weightGrams?: number,
): CartLine {
  return {
    product: { id, name: id, unitPriceCents: 100, weightGrams },
    quantity,
  };
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts zero for both parameters", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1)], 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 6000)).toBe(0);
    });

    it("charges when subtotal below free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 4999)).toBe(599);
    });

    it("charges when no freeOverCents is set regardless of subtotal", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([makeLine("a", 1)], 1_000_000),
      ).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 10.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart where all products have no weight", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 3)], 5000),
      ).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      // 200g * 2 = 400g <= 500g → 300 cents
      expect(
        calc.computeShippingCents([makeLine("a", 2, 200)], 5000),
      ).toBe(300);
    });

    it("selects exact boundary of first bracket", () => {
      // 500g exactly
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 5000),
      ).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      // 501g → 600 cents
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 5000),
      ).toBe(600);
    });

    it("selects last bracket at its boundary", () => {
      // 2000g exactly → 1000 cents
      expect(
        calc.computeShippingCents([makeLine("a", 1, 2000)], 5000),
      ).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g → overflow 1500 cents
      expect(
        calc.computeShippingCents([makeLine("a", 1, 2001)], 5000),
      ).toBe(1500);
    });

    it("uses last bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 1500g, exceeds all → last bracket cost = 600
      expect(
        noOverflow.computeShippingCents([makeLine("a", 1, 1500)], 5000),
      ).toBe(600);
    });

    it("sorts brackets correctly even if provided out of order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g should hit the 500g bracket = 300
      expect(
        unordered.computeShippingCents([makeLine("a", 1, 400)], 5000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 300*2 + 200*1 = 800g → bracket ≤1000 → 600
      const lines: CartLine[] = [
        makeLine("a", 2, 300),
        makeLine("b", 1, 200),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

